"""Build June 1982 process comparison and Team Edition review; no financial forecasts."""
from pathlib import Path
import json,hashlib
from memory_manufacturing import policy,selected,evaluate
R=Path(__file__).resolve().parents[1]
load=lambda n:json.loads((R/n).read_text())
p=policy(); program=load('generated/catalogs/team-development-program.json'); costs=load('generated/models/manufacturing-costs.json'); pricing=load('generated/models/pricing-results.json')
cutoff='1982-06-15'; winner=selected(1982); candidates=[]
for recipe in p['memory_recipes']:
 if recipe['node_um'] not in p['wafer_cost_by_year']['1982']:continue
 wafer=p['wafer_cost_by_year']['1982'][recipe['node_um']];ev=evaluate(recipe,wafer)
 candidates.append({'recipe_id':recipe['id'],'node_um':recipe['node_um'],'available_from':recipe['available_from'],'eligible':recipe['available_from']<=cutoff,'selected':recipe['id']==winner['id'],'die_area_mm2':recipe['die_area_mm2'],'processed_wafer_before_repair_usd':wafer,**{k:round(v,6) for k,v in ev.items()}})
w=next(r for r in candidates if r['selected']); fine=next(r for r in candidates if r['recipe_id']=='dram64_275um_repair')
fine_recipe=next(r for r in p['memory_recipes'] if r['id']==fine['recipe_id'])
# Fixed package/test cash cost; solve wafer cost at the winner's packaged unit cost.
breakeven=(w['good_packaged_chip_cost_usd']*.93-1.95)*(fine['good_packaged_dies_per_wafer']/.93)-fine_recipe.get('repair_cost_per_wafer_usd',0)
report={'as_of':cutoff,'basis':'Existing scenario recipes and dated availability, not measured production yield or historical foundry quotations.','selected_recipe':winner['id'],'scope':'Lowest recurring packaged 64K RAM cost among qualified recipes. Not a capital-inclusive profitability or capacity-utilization decision. ERAv1 and other existing logic chips retain 3 µm; no qualified shrink recipe is assumed for them.','candidates':candidates,'275um_processed_wafer_breakeven_before_repair_usd':round(breakeven,2),'memory_policy_sha256':hashlib.sha256((R/'generated/catalogs/memory-manufacturing.json').read_bytes()).hexdigest(),'investment_status':'No new equipment selected or charged. July 2 µm remains a future option; existing staged process investments are not recalculated.'}
(R/'generated/models/manufacturing-review-1982.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n')
lines=['# Team Edition launch and June 15, 1982 pricing','', 'AION Development System — Team Edition enters the offering in November 1981. November 19 is the project’s selected scenario date, not a sourced historical opening date.','', '## Offering','', '- One Artemis PRO server entitlement and four concurrent developer sessions; hardware and networking sold separately.','- AIONix Server adds default users, groups, authentication, project permissions, quotas and administration in its November revision.','- Repository: atomic multi-file commits, branches, release labels, comments, diffs and rollback; isolated workspaces and revision-stable references.','- Collaboration: text channels and posts referencing files/revisions; shared meetings, calendar, tasks, ownership and milestones.','- C Development Environment 2 loads over the network and runs locally on Artemis, Aurelia and Aurelia+. Compact Z80 clients use overlays and queue heavy/ERA builds to the server.','- CP/M/Z80 and AIONix/ERA are initial targets. Shared C and Breakthru TUI contracts reduce porting work; target-specific adapters, libraries and testing remain necessary. Apple and Commodore are roadmap targets only.','- Recommended server: 1 MiB Artemis PRO. Its existing 5 MB disk supports bounded pilot projects, not an unlimited complex-product repository. Rotate floppy backups and archive history. Larger qualified storage is a prerequisite for substantial deployments and is not included or priced as an invented shipping accessory.','- Four developers is a qualification target. Test recovery, access controls, concurrent edits, conflicts, backup restoration and both target builds before claiming production robustness.','', '## Campaign and staged investment costs','', '**Complex products. Whole teams. One development environment.**','', '“Your team’s development environment should outlast any single computer architecture.” Demonstrate a task, branch, discussion, conflict resolution, two target builds, testing and labelled release. Treat “most robust” as an ambition, not an established comparative claim.','', '| Timing | Activity | Budget USD |','|---|---|---:|']
for row in program['campaign_costs']:lines.append(f"| {row['period']} | {row['category']} | ${row['usd']:,.0f} |")
lines+=['', '**Campaign provision: $276,000**, including $36,000 contingency. **Development/QA/documentation provision: $1,380,000**, including $180,000 contingency. Gross staged provision: **$1,656,000**. Staffing and campaign amounts are planning assumptions itemized in [the program ledger](generated/catalogs/team-development-program.json).','', 'These are pending investment-cost inputs, not additions to the investment model. Reconcile overlap with previously funded engineering, marketing and equipment before booking incremental amounts. Existing sales, marketing totals, investment totals, ecosystem forecasts and ROI files remain unchanged. Their recorded source hashes still identify the previous model inputs; integration validators may report staleness until market reaction is approved. No sales uplift, conversion rate, payback or ROI is inferred.','', '## Which manufacturing line is cheaper?','', '| Recipe | Eligible June 15? | Die area mm² | Yield after repair | Packaged 64K chip USD |','|---|---|---:|---:|---:|']
for r in candidates:lines.append(f"| {r['recipe_id']} | {'Yes' if r['eligible'] else 'No — '+r['available_from']} | {r['die_area_mm2']:g} | {r['die_yield']*100:.2f}% | ${r['good_packaged_chip_cost_usd']:.2f} |")
lines += ['', f"Select **repaired 3 µm RAM at ${w['good_packaged_chip_cost_usd']:.2f}**. The qualified 2.75 µm recipe costs ${fine['good_packaged_chip_cost_usd']:.2f}; its smaller die does not yet offset wafer cost and yield. At unchanged yield, its processed-wafer price would need to fall from $308 to approximately **${breakeven:.2f} before repair** to tie 3 µm. The 2 µm recipe is projected cheaper but its RAM release is July 1, after this snapshot.", '', 'This compares recurring production cash cost, including yield, repair, packaging and test. It does not establish whole-factory profitability, capacity sufficiency or capital-inclusive returns. ERAv1 stays on 3 µm. Hardware BOM quantities and memory capacities are unchanged. Existing memory policy is reused rather than assuming every logic chip can shrink. See [machine-readable comparison](generated/models/manufacturing-review-1982.json).','', '## 1982 pricing policy and limitations','', 'For recurring cost C, fee f and comparator B, use P = √(C×B/(1−f)): contribution/net revenue equals the percentage discount below B. If break-even exceeds B, use break-even and disclose the premium. Without a comparator, P = C/((1−f)×0.75), giving 25% contribution on net revenue. Prices below use the normal 25% ComputerLand fee, except existing direct-service rows at 0%.','', '1982 comparator amounts are explicitly **unverified nominal carry-forwards**, not observed 1982 prices. Costs are June 15 planning estimates: $8.30/h base wage, $0.047/kWh power, overhead index 1.43 and itemized OEM-price assumptions. The future market review should replace comparator estimates before treating these as final competitive prices.','', 'Team Edition costs **$838.38** per package, including 12 disks, 1,000 pages, 20 onboarding staff-hours and 12 first-year support staff-hours. Its approved 50%-reduced adoption price is **$745.23**, with hardware extra and a $279.46 dealer-channel loss at the June-1982 cost proxy. This is an explicit exception to the 25% contribution fallback. No NRE or marketing amortization is hidden in this recurring cost; the price is not evidence of development-cost recovery. Client/server edition rows are included distribution components, not separately priced licenses. Additional seats and paid renewals remain unpriced roadmap items.','', '## Complete June 15, 1982 price list','', 'All amounts nominal USD before tax. Rows are alternative purchase units; never sum bundles and their contents. † = existing announced hardware with shipping unconfirmed. BPI receipts belong to independent BPI Systems.','', '| Offering | Recurring cost | Retail | Contribution / net | Proxy discount |','|---|---:|---:|---:|---:|']
for r in pricing['products']:
 s=r['snapshots']['1982'];b=s.get('pricing_balance',{});discount=b.get('discount_pct')
 if s['retail_price_usd'] is None:continue
 lines.append(f"| {r['name']}{' †' if r['announced_only'] else ''} | ${s['manufacturing_cost_usd']:,.2f} | ${s['retail_price_usd']:,.2f} | {b['margin_pct']:.2f}% | {str(discount)+'%' if discount is not None else 'No proxy'} |")
